code.C:
#include <stdio.h>
int main() {
    char s[1005], d1[10], d2[10];
    if (scanf("%s %s %s", s, d1, d2) != 3) return 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == d1[0]) s[i] = d2[0];
    }
    printf("%s\n", s);
    return 0;
}

